package pl.trenerai.web;

import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import pl.trenerai.model.UserSettings; import pl.trenerai.repository.UserSettingsRepository; import pl.trenerai.service.*;
@Controller @RequestMapping("/settings") public class SettingsController { private final CurrentUserService current;private final UserSettingsRepository settings;private final SecretCrypto crypto; public SettingsController(CurrentUserService c,UserSettingsRepository s,SecretCrypto crypto){current=c;settings=s;this.crypto=crypto;} @GetMapping String page(Model model){model.addAttribute("settings",current.settings());model.addAttribute("aiProviders",AiProviderCatalog.providers());model.addAttribute("aiModels",AiProviderCatalog.models());return "settings";} @PostMapping String save(@RequestParam String openAiKey,@RequestParam String aiProvider,@RequestParam String openAiModel,@RequestParam String stravaClientId,@RequestParam String stravaClientSecret){if(!AiProviderCatalog.isSupported(aiProvider,openAiModel))throw new IllegalArgumentException("Nieobsługiwane połączenie dostawcy i modelu AI.");UserSettings set=current.settings();if(!set.getAiProvider().equals(aiProvider)&&openAiKey.isBlank())throw new IllegalArgumentException("Po zmianie dostawcy wklej jego klucz API.");if(!openAiKey.isBlank())set.setOpenAiKeyEncrypted(crypto.encrypt(openAiKey));set.setAiProvider(aiProvider);set.setOpenAiModel(openAiModel);if(!stravaClientId.isBlank())set.setStravaClientIdEncrypted(crypto.encrypt(stravaClientId));if(!stravaClientSecret.isBlank())set.setStravaClientSecretEncrypted(crypto.encrypt(stravaClientSecret));settings.save(set);return "redirect:/settings?saved";} }
